import{_ as r,l as s,o as e,c as l,v as t,p as n,x as o,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const I=JSON.parse('{"title":"方法 JIT 与热点","description":"","frontmatter":{"title":"方法 JIT 与热点","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/method-jit.md","filePath":"cs/method-jit.md","lastUpdated":1789023840000}'),h={name:"cs/method-jit.md"};function T(m,a,_,f,u,A){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="方法-jit-与热点" tabindex="-1">方法 JIT 与热点 <a class="header-anchor" href="#方法-jit-与热点" aria-label="Permalink to &quot;方法 JIT 与热点&quot;">​</a></h1><div class="epigraph"><p>计数调用或回边，过阈值则把整方法编译成 native，替换入口。冷方法留在解释器，摊还编译成本。</p><footer>—— 据 Deutsch and Schiffman；Aycock, A Brief History of Just-In-Time；HotSpot 方法编译对照整理</footer></div><p>上一课<a href="/cs/threaded-dispatch">线程化分派</a> 仍逐条解释。缺口是 <strong>JIT</strong>：热点方法一次编译，多次执行。本课钉方法级、计数、替换，追踪 JIT 下一课。不写去优化。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>AOT 编译全部，启动慢、体积大。纯解释启动快、峰值慢。JIT：用轮廓（解释时计数）决定。缺口是<strong>编译单位 = 方法</strong>，不是 ELF 全程序。</p><p>入口：调用点从解释器桩改成 compiled 入口（或栈上 on-stack replacement 后课）。</p><h3 id="热点不是-pgo-文件" tabindex="-1">热点不是 PGO 文件 <a class="header-anchor" href="#热点不是-pgo-文件" aria-label="Permalink to &quot;热点不是 PGO 文件&quot;">​</a></h3><p>PGO 是另一次运行的离线轮廓；JIT 轮廓是本次进程的。可结合：AOT 用 PGO，JVM 用在线。</p><p><span class="marginnote">Deutsch–Schiffman 已把 JIT 当 Smalltalk 路径。Aycock 综述。HotSpot。本课方法 JIT；TraceMonkey 下一课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每方法 invocation/backedge 计数。阈值到：编译队列（可后台线程）。安装：更新调用点、vtable。失败：保留解释器。</p>',11)),(e(),n(p,null,{default:o(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INT%5B%22%E8%A7%A3%E9%87%8A%20%2F%20%E8%AE%A1%E6%95%B0%22%5D%20--%3E%20HOT%5B%22%E8%BF%87%E9%98%88%E5%80%BC%22%5D%0A%20%20HOT%20--%3E%20COMP%5B%22%E6%96%B9%E6%B3%95%E7%BC%96%E8%AF%91%22%5D%0A%20%20COMP%20--%3E%20ENT%5B%22%E6%9B%BF%E6%8D%A2%E5%85%A5%E5%8F%A3%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与<a href="/cs/inlining-heuristics">内联</a>：JIT 内联用在线热度更准。与 LTO：JIT 看见的是已加载类，开世界仍在（新类）。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>编译线程与应用线程：队列、代码缓存上限、回收冷码。不要在持锁时同步编译导致卡顿——启发。</p><p>ISA：JIT 是<a href="/cs/cross-compile-triple">交叉</a> 的特例，目标=本机。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写追踪。后课默认：热点方法可编译。下一课追踪 JIT：以路径为单位而非方法。</p><p>也不把 JIT 当恶意运行时注入教程。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>方法 JIT：计数 → 编译整方法 → 换入口。</li><li>摊还启动与峰值。</li><li>代码缓存与后台编译是工程。</li><li>出处：Deutsch and Schiffman；Aycock；HotSpot 文献。</li></ul>',9))])}const J=r(h,[["render",T]]);export{I as __pageData,J as default};
